import sys
from bisect import bisect_left, bisect_right


def is_number(word):
    return 0 < len(word) <= 19 and word.isdigit()


def main():
    lines = sys.stdin.buffer.read().split(b"\n")
    pos = 0
    n = int(lines[pos])
    pos += 1
    ids, stamps, pair_lists = [], [], []
    for line in lines[pos:pos + n]:
        tok = line.split(b" ")
        if len(tok) < 4 or len(tok) % 2 or tok[0] != b"id" or tok[2] != b"timestamp":
            continue
        if not is_number(tok[1]) or not is_number(tok[3]):
            continue
        keys = tok[0::2]  # id, timestamp and every file path must be distinct
        if len(set(keys)) != len(keys):
            continue
        ids.append(int(tok[1]))
        stamps.append(int(tok[3]))
        pair_lists.append(tok[4:])
    pos += n
    count = len(ids)
    parent = list(range(count))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # Union commits that share an exact (path, opaque id) pair with its first owner.
    anchor = {}
    for c, words in enumerate(pair_lists):
        for j in range(0, len(words), 2):
            other = anchor.setdefault((words[j], words[j + 1]), c)
            if other != c:
                a, b = find(c), find(other)
                if a != b:
                    parent[a] = b
    # Only after every merge: one path with two ids inside a component is ambiguous.
    owner = {}
    for c, words in enumerate(pair_lists):
        root = find(c)
        for j in range(0, len(words), 2):
            if owner.setdefault((root, words[j]), words[j + 1]) != words[j + 1]:
                sys.stdout.write("AMBIGUOUS INPUT!\n")
                return
    groups = {}
    for c in range(count):
        groups.setdefault(find(c), []).append(c)
    sorted_groups = {}
    for root, members in groups.items():
        members.sort(key=lambda c: (stamps[c], ids[c]))
        sorted_groups[root] = ([stamps[c] for c in members], [ids[c] for c in members])
    r = int(lines[pos])
    pos += 1
    out = []
    for line in lines[pos:pos + r]:
        tok = line.split(b" ")
        lo, hi = int(tok[0]), int(tok[1])
        c = anchor.get((tok[2], tok[3]))
        if c is not None:
            # The component's commits with lo <= ts <= hi form one contiguous run.
            ts, cid = sorted_groups[find(c)]
            i = bisect_left(ts, lo)
            j = max(i, bisect_right(ts, hi))
            out.append("".join(f"{x} " for x in cid[i:j]))
        else:
            out.append("")
    out.append("")
    sys.stdout.write("\n".join(out))


