import java.io.*;
import java.util.*;

public class Main {
    static byte[] in;
    static int p = 0;
    static int[] ws = new int[1 << 10], we = new int[1 << 10]; // word starts / ends of the current line
    static int words;
    static int[] parent;

    // Splits the next line on single spaces (empty words kept) into ws/we.
    static void nextLine() {
        int e = p;
        while (e < in.length && in[e] != '\n') e++;
        words = 0;
        int a = p;
        for (int i = p; i <= e; i++) {
            if (i == e || in[i] == ' ') {
                if (words == ws.length) {
                    ws = Arrays.copyOf(ws, words * 2);
                    we = Arrays.copyOf(we, words * 2);
                }
                ws[words] = a;
                we[words++] = i;
                a = i + 1;
            }
        }
        p = e < in.length ? e + 1 : e;
    }

    static boolean is(int w, String s) {
        if (we[w] - ws[w] != s.length()) return false;
        for (int i = 0; i < s.length(); i++) if (in[ws[w] + i] != s.charAt(i)) return false;
        return true;
    }

    static boolean digits(int w) {
        int len = we[w] - ws[w];
        if (len == 0 || len > 19) return false;
        for (int i = ws[w]; i < we[w]; i++) if (in[i] < '0' || in[i] > '9') return false;
        return true;
    }

    static long number(int w) {
        long v = 0;
        for (int i = ws[w]; i < we[w]; i++) v = v * 10 + (in[i] - '0');
        return v;
    }

    static long firstNumber() {
        nextLine();
        long v = 0;
        for (int i = ws[0]; i < we[0]; i++) if (in[i] >= '0' && in[i] <= '9') v = v * 10 + (in[i] - '0');
        return v;
    }

    static boolean same(int a, int aLen, int b, int bLen) {
        if (aLen != bLen) return false;
        for (int i = 0; i < aLen; i++) if (in[a + i] != in[b + i]) return false;
        return true;
    }

    static int hash(int from, int len) {
        int h = 0x811C9DC5;
        for (int i = from; i < from + len; i++) h = (h ^ in[i]) * 0x01000193;
        return h ^ (h >>> 16);
    }

    // Whether two of the keys (the words at even positions) are equal.
    static boolean duplicateKeys() {
        if (words <= 32) {
            for (int a = 0; a < words; a += 2)
                for (int b = a + 2; b < words; b += 2)
                    if (same(ws[a], we[a] - ws[a], ws[b], we[b] - ws[b])) return true;
            return false;
        }
        HashSet<String> keys = new HashSet<>();
        for (int j = 0; j < words; j += 2) if (!keys.add(new String(in, ws[j], we[j] - ws[j]))) return true;
        return false;
    }

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    // Pairs are byte ranges of the input: "path opaque" starts at pairStart, the path is pathLen long.
    static int[] pairStart = new int[1 << 16], pairLen = new int[1 << 16], pathLen = new int[1 << 16];
    static int pairs = 0;
    // ponytail: open-addressing tables over byte ranges stand in for string hash maps (no allocation per pair).
    static int[] anchorSlot; // pair index + 1 of the first occurrence of each exact pair
    static int[] anchorCommit;
    static int mask;

    static int anchorFind(int from, int len) {
        int i = hash(from, len) & mask;
        while (anchorSlot[i] != 0) {
            int j = anchorSlot[i] - 1;
            if (same(pairStart[j], pairLen[j], from, len)) return i;
            i = (i + 1) & mask;
        }
        return i;
    }

    public static void main(String[] args) throws IOException {
        in = System.in.readAllBytes();
        long n = firstNumber();
        long[] ids = new long[16], ts = new long[16];
        int[] begin = new int[17];
        int count = 0;
        for (long i = 0; i < n; i++) {
            nextLine();
            if (words < 4 || words % 2 != 0 || !is(0, "id") || !is(2, "timestamp") || !digits(1) || !digits(3)) continue;
            if (duplicateKeys()) continue; // id, timestamp and every path must be distinct
            if (count == ids.length) {
                ids = Arrays.copyOf(ids, count * 2);
                ts = Arrays.copyOf(ts, count * 2);
                begin = Arrays.copyOf(begin, count * 2 + 1);
            }
            ids[count] = number(1);
            ts[count] = number(3);
            begin[count++] = pairs;
            for (int j = 4; j + 1 < words; j += 2) {
                if (pairs == pairStart.length) {
                    pairStart = Arrays.copyOf(pairStart, pairs * 2);
                    pairLen = Arrays.copyOf(pairLen, pairs * 2);
                    pathLen = Arrays.copyOf(pathLen, pairs * 2);
                }
                pairStart[pairs] = ws[j];
                pairLen[pairs] = we[j + 1] - ws[j];
                pathLen[pairs++] = we[j] - ws[j];
            }
        }
        begin[count] = pairs;
        parent = new int[count];
        for (int c = 0; c < count; c++) parent[c] = c;
        int cap = Integer.highestOneBit(Math.max(2, pairs) * 2) * 2;
        mask = cap - 1;
        anchorSlot = new int[cap];
        anchorCommit = new int[cap];
        // Union commits that share an exact (path, opaque id) pair with its first owner.
        for (int c = 0; c < count; c++) {
            for (int j = begin[c]; j < begin[c + 1]; j++) {
                int s = anchorFind(pairStart[j], pairLen[j]);
                if (anchorSlot[s] == 0) {
                    anchorSlot[s] = j + 1;
                    anchorCommit[s] = c;
                } else {
                    int a = find(c), b = find(anchorCommit[s]);
                    if (a != b) parent[a] = b;
                }
            }
        }
        int[] root = new int[count], pairRoot = new int[pairs];
        for (int c = 0; c < count; c++) {
            root[c] = find(c);
            for (int j = begin[c]; j < begin[c + 1]; j++) pairRoot[j] = root[c];
        }
        // Only after every merge: one path with two ids inside a component is ambiguous.
        int[] ownerSlot = new int[cap]; // pair index + 1, keyed by (component, path)
        for (int c = 0; c < count; c++) {
            for (int j = begin[c]; j < begin[c + 1]; j++) {
                int i = (hash(pairStart[j], pathLen[j]) ^ (root[c] * 0x9E3779B1)) & mask;
                while (true) {
                    if (ownerSlot[i] == 0) {
                        ownerSlot[i] = j + 1;
                        break;
                    }
                    int k = ownerSlot[i] - 1;
                    if (pathLen[k] == pathLen[j] && pairRoot[k] == root[c]
                            && same(pairStart[k], pathLen[k], pairStart[j], pathLen[j])) {
                        if (!same(pairStart[k], pairLen[k], pairStart[j], pairLen[j])) {
                            System.out.print("AMBIGUOUS INPUT!\n");
                            return;
                        }
                        break;
                    }
                    i = (i + 1) & mask;
                }
            }
        }
        // Order commits by (component, timestamp, id); each component is one contiguous block.
        Integer[] order = new Integer[count];
        for (int c = 0; c < count; c++) order[c] = c;
        final long[] tsF = ts, idsF = ids;
        Arrays.sort(order, (x, y) -> root[x] != root[y] ? Integer.compare(root[x], root[y])
                : tsF[x] != tsF[y] ? Long.compare(tsF[x], tsF[y]) : Long.compare(idsF[x], idsF[y]));
        int[] blockStart = new int[count + 1], blockEnd = new int[count + 1];
        long[] sortedTs = new long[count];
        for (int k = 0; k < count; k++) {
            int r = root[order[k]];
            if (k == 0 || root[order[k - 1]] != r) blockStart[r] = k;
            blockEnd[r] = k + 1;
            sortedTs[k] = ts[order[k]];
        }
        long q = firstNumber();
        StringBuilder out = new StringBuilder();
        for (long i = 0; i < q; i++) {
            nextLine();
            long lo = number(0), hi = number(1);
            int s = count > 0 ? anchorFind(ws[2], we[3] - ws[2]) : -1;
            if (s >= 0 && anchorSlot[s] != 0) {
                int r = root[anchorCommit[s]], a = blockStart[r], b = blockEnd[r];
                while (a < b) { // first position with ts >= lo
                    int mid = (a + b) >>> 1;
                    if (sortedTs[mid] < lo) a = mid + 1;
                    else b = mid;
                }
                for (int k = a; k < blockEnd[r] && sortedTs[k] <= hi; k++) out.append(ids[order[k]]).append(' ');
            }
            out.append('\n');
        }
        PrintWriter w = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        w.write(out.toString());
        w.flush();
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

func digits(s string) bool {
	if len(s) == 0 || len(s) > 19 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func number(s string) uint64 {
	var v uint64
	for i := 0; i < len(s); i++ {
		v = v*10 + uint64(s[i]-'0')
	}
	return v
}

type ownerKey struct {
	root int32
	path string
}

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	in := string(raw)
	p := 0
	nextLine := func() string {
		e := strings.IndexByte(in[p:], '\n')
		var s string
		if e < 0 {
			s, p = in[p:], len(in)
		} else {
			s, p = in[p:p+e], p+e+1
		}
		return s
	}
	// Word boundaries of a line split on single spaces (empty words kept).
	var starts []int
	split := func(s string) []int {
		starts = starts[:0]
		starts = append(starts, 0)
		for i := 0; i < len(s); i++ {
			if s[i] == ' ' {
				starts = append(starts, i+1)
			}
		}
		return starts
	}
	word := func(s string, st []int, w int) string {
		if w+1 < len(st) {
			return s[st[w] : st[w+1]-1]
		}
		return s[st[w]:]
	}
	n, _ := strconv.Atoi(strings.TrimSpace(nextLine()))
	var ids, ts []uint64
	var pairKey, pairPath []string // "path opaque" and its path, substrings of the input
	begin := []int{}
	for i := 0; i < n; i++ {
		line := nextLine()
		st := split(line)
		words := len(st)
		if words < 4 || words%2 != 0 || word(line, st, 0) != "id" || word(line, st, 2) != "timestamp" ||
			!digits(word(line, st, 1)) || !digits(word(line, st, 3)) {
			continue
		}
		dup := false // id, timestamp and every path must be distinct
		keys := map[string]bool{}
		for j := 0; j < words && !dup; j += 2 {
			k := word(line, st, j)
			dup = keys[k]
			keys[k] = true
		}
		if dup {
			continue
		}
		ids = append(ids, number(word(line, st, 1)))
		ts = append(ts, number(word(line, st, 3)))
		begin = append(begin, len(pairKey))
		for j := 4; j+1 < words; j += 2 {
			path := word(line, st, j)
			pairKey = append(pairKey, line[st[j]:st[j]+len(path)+1+len(word(line, st, j+1))])
			pairPath = append(pairPath, path)
		}
	}
	count := len(ids)
	begin = append(begin, len(pairKey))
	parent := make([]int32, count)
	for c := range parent {
		parent[c] = int32(c)
	}
	find := func(x int32) int32 {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	// Union commits that share an exact (path, opaque id) pair with its first owner.
	anchor := make(map[string]int32, len(pairKey))
	for c := 0; c < count; c++ {
		for j := begin[c]; j < begin[c+1]; j++ {
			if other, ok := anchor[pairKey[j]]; ok {
				if a, b := find(int32(c)), find(other); a != b {
					parent[a] = b
				}
			} else {
				anchor[pairKey[j]] = int32(c)
			}
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	// Only after every merge: one path with two ids inside a component is ambiguous.
	owner := make(map[ownerKey]string, len(pairKey))
	for c := 0; c < count; c++ {
		r := find(int32(c))
		for j := begin[c]; j < begin[c+1]; j++ {
			k := ownerKey{r, pairPath[j]}
			if prev, ok := owner[k]; !ok {
				owner[k] = pairKey[j]
			} else if prev != pairKey[j] { // same path, so same key iff same id
				w.WriteString("AMBIGUOUS INPUT!\n")
				return
			}
		}
	}
	root := make([]int32, count)
	order := make([]int32, count)
	for c := range order {
		order[c], root[c] = int32(c), find(int32(c))
	}
	// Order commits by (component, timestamp, id); each component is one contiguous block.
	sort.Slice(order, func(x, y int) bool {
		a, b := order[x], order[y]
		if root[a] != root[b] {
			return root[a] < root[b]
		}
		if ts[a] != ts[b] {
			return ts[a] < ts[b]
		}
		return ids[a] < ids[b]
	})
	blockStart, blockEnd := make([]int, count), make([]int, count)
	sortedTs := make([]uint64, count)
	for k, c := range order {
		r := root[c]
		if k == 0 || root[order[k-1]] != r {
			blockStart[r] = k
		}
		blockEnd[r] = k + 1
		sortedTs[k] = ts[c]
	}
	q, _ := strconv.Atoi(strings.TrimSpace(nextLine()))
	num := make([]byte, 0, 24)
	for i := 0; i < q; i++ {
		line := nextLine()
		st := split(line)
		lo, hi := number(word(line, st, 0)), number(word(line, st, 1))
		if c, ok := anchor[line[st[2]:]]; ok {
			r := root[c]
			end := blockEnd[r]
			// first position with ts >= lo
			k := blockStart[r] + sort.Search(end-blockStart[r], func(x int) bool { return sortedTs[blockStart[r]+x] >= lo })
			for ; k < end && sortedTs[k] <= hi; k++ {
				num = strconv.AppendUint(num[:0], ids[order[k]], 10)
				num = append(num, ' ')
				w.Write(num)
			}
		}
		w.WriteByte('\n')
	}
}
